        print("TREE-END")
        for id in ["probe-btn", "probe-div", "probe-div-role", "probe-li", "probe-scroll", "probe-input", "probe-img"] {
            let el = app.descendants(matching: .any)[id]
            print("PROBE \(id) exists=\(el.exists)")
        }
    }
}

