import React from "react";
import FastRefresh from "../../../vite/FastRefresh.jsx";

/**
 * Head component — inlines critical CSS as <style> and renders JS as <script type="module">.
 * Critical CSS is small (~15-25KB) thanks to natural Vite code-splitting.
 * Route-cached deferred CSS is inlined here on repeat visits; new deferred CSS still appends after body.
 */
export function Head(props) {
  const {
    inlineCss,
    deferredRouteInlineCss,
    jsScripts,
    criticalPreloadLinks,
    deferredPreloadLinks,
    metaTags,
    isBot,
    publicAssetPath,
    children
  } = props;
  return <head>
            <meta charSet="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
            {process.env.NODE_ENV === "development" && <FastRefresh />}

            {publicAssetPath && <link rel="preconnect" href={publicAssetPath} />}
            {publicAssetPath && <link rel="dns-prefetch" href={publicAssetPath} />}
            {!isBot && criticalPreloadLinks}
            {/* Warm-cache modulepreloads from prior SSRs (URLs not in critical scripts) */}
            {!isBot && deferredPreloadLinks}
            {metaTags && metaTags}

            {/* Inline critical CSS — prevents FOUC/CLS */}
            {/* nosemgrep: typescript.react.security.audit.react-dangerouslysetinnerhtml.react-dangerouslysetinnerhtml - inlineCss is compiled CSS read from disk (readCssFromDisk), sourced from the app's own build output, never from request/user input. */}
            {inlineCss && <style dangerouslySetInnerHTML={{
      __html: inlineCss
    }} />}

            {/* Deferred CSS from prior SSRs on this route — avoids late layout from post-body <style> */}
            {/* nosemgrep: typescript.react.security.audit.react-dangerouslysetinnerhtml.react-dangerouslysetinnerhtml - deferredRouteInlineCss is compiled CSS read from disk (readCssFromDisk), sourced from the app's own build output, never from request/user input. */}
            {deferredRouteInlineCss && <style dangerouslySetInnerHTML={{
      __html: deferredRouteInlineCss
    }} />}

            {/* JS modules */}
            {!isBot && jsScripts}

            {children}
        </head>;
}
import React from "react";
const DEFAULT_SAFE_AREA = {
  top: 0,
  right: 0,
  bottom: 0,
  left: 0
};

// React does not escape the body of an inline <script>, so a "</script>" inside
// serialized state would end the block early. The JS parser reads \u003c back as
// "<", so the payload the client sees is unchanged.
const serialize = value => JSON.stringify(value).replace(/</g, "\\u003c");

/**
 * Body component which will be used in page component
 * @param {object} jsx - page jsx code
 * @param {number|string} statusCode - document request status code
 * @param {object} initialState - initial state object for redux store
 * @param {object} fetcherData - contains data from executing serverFetcher function
 * @param {object} children - contains any child elements defined within the component
 */
export function Body(props) {
  const {
    jsx = "",
