    fetcherData = {},
    children,
    safeArea = DEFAULT_SAFE_AREA,
    nativeWebView = false
  } = props;
  return <body>
            <script
    /* eslint-disable-next-line risxss/catch-potential-xss-react */ dangerouslySetInnerHTML={{
      __html: `window.__SAFE_AREA_INITIAL__ = ${JSON.stringify(safeArea)}; window.__CATALYST_NATIVE_WEBVIEW__ = ${nativeWebView ? "true" : "false"}`
    }} />
            {process.env.NODE_ENV === "development" &&
    // Base pinned to Vite's resolved base by server/expressServer.js.
    <script type="module" src={`${process.env.APP_MOUNT_PATH || ""}/client/index.js`}></script>}
            {jsx}
            <script
    /* eslint-disable */ dangerouslySetInnerHTML={{
      __html: `
                    window.__INITIAL_STATE__ = ${serialize(initialState)}
                    window.__STATUS_CODE__ = ${JSON.stringify(statusCode || null)}
                    window.__ROUTER_INITIAL_DATA__ = ${serialize(fetcherData)}
            `
    }} />

            {children}
        </body>;
}
