                        onClick={() => openCollection(c)}
                    >
                        {c.title}
                    </button>
                ))}
            </nav>
            {featured && (
                <button
                    type="button"
                    className="featured"
                    aria-label="featured-collection"
                    onClick={() => openCollection(featured)}
