// Everbloom styles. Tokens from spec/design/screens/Tokens.dc.html.
$background: #ffffff;
$surface: #f4f1ec;
$skeleton: #ede9e3;
$border: #e6e1d9;
$text: #1c1b19;
$muted: #6e6a63;
$sale: #b4361e;
$body-text: #3d3a35;

$tabbar: 49px;
$safe-top: env(safe-area-inset-top);
$safe-bottom: env(safe-area-inset-bottom);

*,
*::before,
*::after {
    box-sizing: border-box;
}

html,
body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: $background;
    color: $text;
    font-family: -apple-system, BlinkMacSystemFont, system-ui, Roboto, "Helvetica Neue", sans-serif;
    font-size: 15px;
    line-height: 22px;
    -webkit-text-size-adjust: 100%;
    -webkit-tap-highlight-color: transparent;
    -webkit-touch-callout: none;
    -webkit-user-select: none;
    user-select: none;
    overscroll-behavior: none;
}

#app {
    height: 100%;
}

button {
    font: inherit;
    color: inherit;
    background: none;
    border: 0;
    padding: 0;
    margin: 0;
    text-align: inherit;
    cursor: pointer;
}

h1,
h2,
p {
    margin: 0;
}

img {
    display: block;
    background: $surface;
    object-fit: cover;
}

// ---------- App frame, stacks, tab bar ----------

.app {
    position: fixed;
    inset: 0;
    overflow: hidden;
}

.layer {
    position: absolute;
    inset: 0;
    background: $background;
}

.layer.hidden {
    visibility: hidden;
    content-visibility: hidden;
    pointer-events: none;
}

.screen {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    padding-top: $safe-top;
}

.screen.with-tabs {
    bottom: calc(#{$tabbar} + #{$safe-bottom});
}

.scroll {
    flex: 1;
    min-height: 0;
    position: relative;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.scroll.column {
    display: flex;
    flex-direction: column;
}

.list-end {
    height: 24px;
}

.list-footer {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 8px 16px 24px;
}

.tabbar {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: calc(#{$tabbar} + #{$safe-bottom});
    padding-bottom: $safe-bottom;
    background: $background;
    border-top: 1px solid $border;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.tab {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    color: $muted;
    font-size: 11px;
    line-height: 13px;
    font-weight: 500;
}

.tab.active {
    color: $text;
    font-weight: 600;
}

.badge {
    position: absolute;
    top: 4px;
    left: calc(250% / 3 + 6px); // centre of the third column + 6
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: $sale;
    color: #ffffff;
    font-size: 11px;
    line-height: 18px;
    font-weight: 700;
    text-align: center;
    pointer-events: none;
}

// ---------- Shared pieces ----------

.h2 {
    font-size: 17px;
    line-height: 22px;
    font-weight: 700;
}

.h3 {
    margin: 0 0 8px;
    font-size: 15px;
    line-height: 22px;
    font-weight: 600;
}

.mb12 {
    margin-bottom: 12px;
}

.px16 {
    padding: 0 16px;
}

.screen-title {
    font-size: 22px;
    line-height: 28px;
    font-weight: 700;
}

.price-row {
    display: flex;
    gap: 6px;
    align-items: baseline;
}

.price {
    font-size: 15px;
    line-height: 20px;
    font-weight: 700;
}

.sale {
    color: $sale;
}

.compare {
    font-size: 13px;
    line-height: 18px;
    color: $muted;
}

.grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 12px;
    row-gap: 20px;
}

.card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
}

.card-img {
    width: 100%;
    aspect-ratio: 3 / 4;
    border-radius: 8px;
}

.card-title {
    font-size: 14px;
    line-height: 18px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.chips,
.carousel,
.sorts {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    overscroll-behavior-x: contain;
}

.chips::-webkit-scrollbar,
.carousel::-webkit-scrollbar,
.sorts::-webkit-scrollbar,
.pdp-carousel::-webkit-scrollbar {
    display: none;
}

.chips {
    gap: 8px;
    padding: 8px 16px 12px;
}

.chip {
    flex-shrink: 0;
    height: 36px;
    padding: 0 14px;
    border-radius: 999px;
    background: $surface;
    font-size: 14px;
    font-weight: 500;
    white-space: nowrap;
}

.carousel {
    gap: 12px;
    padding: 0 16px;
}

.section {
    padding-top: 28px;
}

.section.padded {
    padding: 28px 16px 0;
}

.section-head {
    padding: 0 16px 12px;
}

.btn-primary {
    width: 100%;
    height: 52px;
    border-radius: 12px;
    background: $text;
    color: #ffffff;
    font-size: 16px;
    font-weight: 600;
    text-align: center;
}

.btn-primary:disabled {
    opacity: 0.5;
}

.btn-primary.small {
    width: auto;
    height: 48px;
    padding: 0 24px;
    margin-top: 8px;
}

.btn-secondary {
    height: 48px;
    padding: 0 24px;
    margin-top: 8px;
    border-radius: 12px;
    border: 1px solid $text;
    background: $background;
    font-size: 16px;
    font-weight: 600;
}

.state {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 0 32px;
    text-align: center;
    color: $muted;
}

.state-title {
    font-size: 17px;
    line-height: 22px;
    font-weight: 700;
    color: $text;
}

.state-text {
    font-size: 15px;
    line-height: 22px;
    color: $muted;
}

.state .btn-primary,
.state .btn-secondary {
    color: inherit;
}

.state .btn-primary {
    color: #ffffff;
}

.state .btn-secondary {
    color: $text;
}

.spinner {
    display: block;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    border: 2.5px solid $border;
    border-top-color: $muted;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

.center-spinner {
    display: flex;
    justify-content: center;
    padding: 48px 0;
}

// Skeletons
.sk {
    background: $skeleton;
}

.sk-chip {
    flex-shrink: 0;
    height: 36px;
    border-radius: 999px;
}

.sk-heading {
    width: 120px;
    height: 18px;
    border-radius: 4px;
}

.sk-line {
    height: 14px;
    border-radius: 4px;
    width: 100%;
}

.sk-line.short {
    width: 50%;
}

.sk-title {
    height: 24px;
    width: 70%;
    border-radius: 4px;
}

.sk-price {
    height: 22px;
    width: 30%;
    border-radius: 4px;
}

.grid .card .sk-line {
    margin: 0;
}

// ---------- Home ----------

.home-header {
    height: 44px;
    padding: 0 16px;
    display: flex;
    align-items: center;
}

.wordmark {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: -0.4px;
}

.featured {
    position: relative;
    display: block;
    width: calc(100% - 32px);
    height: 240px;
    margin: 4px 16px 0;
    border-radius: 12px;
    overflow: hidden;
    background: $surface;
}

.featured.sk {
    background: $skeleton;
}

.featured-img {
    width: 100%;
    height: 100%;
    object-position: center 30%;
}

.featured-overlay {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    padding: 16px;
    background: rgba(28, 27, 25, 0.72);
    color: #ffffff;
    display: flex;
    flex-direction: column;
    gap: 2px;
    text-align: left;
}

.featured-label {
    font-size: 12px;
    line-height: 16px;
    font-weight: 600;
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.featured-title {
    font-size: 20px;
    line-height: 25px;
    font-weight: 700;
}

.featured-cta {
    font-size: 14px;
    line-height: 18px;
}

.collection-card {
    flex-shrink: 0;
    width: 140px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.collection-img {
    flex-shrink: 0;
    width: 140px;
    height: 175px;
    border-radius: 8px;
}

.collection-title {
    font-size: 14px;
    line-height: 18px;
    font-weight: 600;
}

// ---------- Collection ----------

.navbar {
    flex-shrink: 0;
    height: 44px;
    padding: 0 8px;
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr) 44px;
    align-items: center;
}

.nav-back {
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.navbar-title {
    font-size: 17px;
    line-height: 22px;
    font-weight: 600;
    text-align: center;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.description {
    flex-shrink: 0;
    padding: 4px 16px 0;
    font-size: 14px;
    line-height: 20px;
    color: $muted;
}

.sorts {
    flex-shrink: 0;
    gap: 8px;
    padding: 12px 16px;
}

.sort {
    flex-shrink: 0;
    height: 32px;
    padding: 0 12px;
    border-radius: 999px;
    border: 1px solid $border;
    background: $background;
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
}

.sort.selected {
    border-color: $text;
    background: $text;
    color: #ffffff;
    font-weight: 600;
}

.scroll > .grid {
    padding: 0 16px;
}

.virtual-body {
    position: relative;
}

// ---------- Product ----------

.pdp-scroll {
    background: $background;
}

.pdp-media {
    position: relative;
    width: 100%;
    aspect-ratio: 3 / 4;
    background: $surface;
}

.pdp-media.sk {
    background: $skeleton;
}

