// Everbloom styles. Tokens from spec/design/screens/Tokens.dc.html.
$background: #ffffff;
$surface: #f4f1ec;
$skeleton: #ede9e3;
$border: #e6e1d9;
$text: #1c1b19;
$muted: #6e6a63;
$sale: #b4361e;
$body-text: #3d3a35;

$tabbar: 49px;
$safe-top: env(safe-area-inset-top);
$safe-bottom: env(safe-area-inset-bottom);

*,
*::before,
*::after {
    box-sizing: border-box;
}

html,
body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: $background;
    color: $text;
    font-family: -apple-system, BlinkMacSystemFont, system-ui, Roboto, "Helvetica Neue", sans-serif;
    font-size: 15px;
    line-height: 22px;
    -webkit-text-size-adjust: 100%;
    -webkit-tap-highlight-color: transparent;
    -webkit-touch-callout: none;
    -webkit-user-select: none;
    user-select: none;
    overscroll-behavior: none;
}

#app {
    height: 100%;
}

button {
    font: inherit;
    color: inherit;
    background: none;
    border: 0;
    padding: 0;
    margin: 0;
    text-align: inherit;
    cursor: pointer;
}

h1,
h2,
p {
    margin: 0;
}

img {
    display: block;
    background: $surface;
    object-fit: cover;
}

// ---------- App frame, stacks, tab bar ----------

.app {
    position: fixed;
    inset: 0;
    overflow: hidden;
}

.layer {
    position: absolute;
    inset: 0;
    background: $background;
}

.layer.hidden {
    visibility: hidden;
    content-visibility: hidden;
    pointer-events: none;
}

.screen {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    padding-top: $safe-top;
}

.screen.with-tabs {
    bottom: calc(#{$tabbar} + #{$safe-bottom});
}

.scroll {
    flex: 1;
    min-height: 0;
    position: relative;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.scroll.column {
    display: flex;
    flex-direction: column;
}

.list-end {
    height: 24px;
}

.list-footer {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 8px 16px 24px;
}

.tabbar {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: calc(#{$tabbar} + #{$safe-bottom});
    padding-bottom: $safe-bottom;
    background: $background;
    border-top: 1px solid $border;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.tab {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    color: $muted;
    font-size: 11px;
    line-height: 13px;
    font-weight: 500;
}

.tab.active {
    color: $text;
    font-weight: 600;
}

.badge {
    position: absolute;
    top: 4px;
    left: calc(250% / 3 + 6px); // centre of the third column + 6
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: $sale;
    color: #ffffff;
    font-size: 11px;
    line-height: 18px;
    font-weight: 700;
    text-align: center;
    pointer-events: none;
}

// ---------- Shared pieces ----------

.h2 {
    font-size: 17px;
    line-height: 22px;
    font-weight: 700;
}

.h3 {
    margin: 0 0 8px;
    font-size: 15px;
    line-height: 22px;
    font-weight: 600;
}

.mb12 {
    margin-bottom: 12px;
}

.px16 {
    padding: 0 16px;
}

.screen-title {
    font-size: 22px;
    line-height: 28px;
    font-weight: 700;
}

.price-row {
    display: flex;
    gap: 6px;
    align-items: baseline;
}

.price {
    font-size: 15px;
    line-height: 20px;
    font-weight: 700;
}

.sale {
    color: $sale;
}

.compare {
    font-size: 13px;
    line-height: 18px;
    color: $muted;
}

.grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 12px;
    row-gap: 20px;
}

.card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
}

.card-img {
    width: 100%;
    aspect-ratio: 3 / 4;
    border-radius: 8px;
}

.card-title {
    font-size: 14px;
    line-height: 18px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.chips,
.carousel,
.sorts {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    overscroll-behavior-x: contain;
}

.chips::-webkit-scrollbar,
.carousel::-webkit-scrollbar,
.sorts::-webkit-scrollbar,
.pdp-carousel::-webkit-scrollbar {
    display: none;
}

.chips {
    gap: 8px;
