cat > scripts/forward-server.mjs <<'EOF'
#!/usr/bin/env node
// Test helper: forwards POST /api on 127.0.0.1:<port> to the mock.shop endpoint.
// Used by scripts/verify-ios.sh to make an "unreachable" endpoint reachable again.
import http from "node:http"

const port = Number(process.argv[2] || 8788)
const target = process.argv[3] || "https://apparel-large-catalog.mock.shop/api"

http.createServer(async (req, res) => {
    const chunks = []
    for await (const c of req) chunks.push(c)
    try {
        const upstream = await fetch(target, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: Buffer.concat(chunks),
        })
        res.writeHead(upstream.status, { "Content-Type": "application/json" })
        res.end(await upstream.text())
    } catch (e) {
        res.writeHead(502)
        res.end(String(e))
    }
}).listen(port, "0.0.0.0", () => console.log(`forwarding :${port} -> ${target}`))
EOF
