#!/bin/sh
# Simulator verification: runs the XCUITest flows in ios/EverbloomUITests against
# the Release simulator build. Screenshots land in /tmp/eb-shots.
# Usage: scripts/verify-ios.sh ["iPhone 17 Pro"]
set -eu
cd "$(dirname "$0")/.."
SIM="${1:-iPhone 17 Pro}"
rm -f /tmp/eb-need-server
rm -rf /tmp/eb-shots
# Start the forwarder for testErrorAndRetry once the test asks for it.
( while [ ! -f /tmp/eb-need-server ]; do sleep 0.5; done
  exec node scripts/forward-server.mjs 8788 ) &
WATCHER=$!
trap 'kill $WATCHER 2>/dev/null; pkill -f "forward-server.mjs 8788" 2>/dev/null; true' EXIT
xcodebuild -project ios/Everbloom.xcodeproj -scheme Everbloom -configuration Release \
  -destination "platform=iOS Simulator,name=$SIM" -derivedDataPath build/ios-test test
EOF
chmod +x scripts/*.sh scripts/*.mjs; (NODE_EXTRA_CA_CERTS=/tmp/zscaler.pem scripts/verify-ios.sh > /tmp/verify.log 2>&1; echo "exit=$?" >> /tmp/verify.log) ; tail -3 /tmp/verify.log; grep -E "error:|Test Case.*(passed|failed)|XCTAssert|failed -" /tmp/verify.log | head -20

